/** Live price for a product: Boards & Panels products carry a `rateKey`
 *  into Settings & Rates, so one admin edit reprices the shop AND the
 *  Interior & Cabinetry estimator together. Everything else uses its
 *  catalog priceNgn. Imported lazily to keep this data module cycle-free
 *  at load time (settings.ts reads localStorage at call time only). */
import { getRates, getCatalogOverrides, getFindsDrafts } from "@/lib/settings";
export function productPrice(p: Product): number {
  // Admin price override (Catalog / Profit tabs) wins over every seed.
  const ov = getCatalogOverrides()[p.slug]?.priceNgn;
  if (typeof ov === "number" && Number.isFinite(ov) && ov > 0) return ov;
  if (p.rateKey) {
    const rates = getRates() as unknown as Record<string, number>;
    const v = rates[p.rateKey];
    if (typeof v === "number" && Number.isFinite(v) && v > 0) return v;
  }
  return p.priceNgn;
}
/** Effective purchase cost for a product: admin override first, then the
 *  researched seed on the product. null = cost not set (never invented). */
export function productCost(p: Product): number | null {
  const ov = getCatalogOverrides()[p.slug];
  if (ov && ov.costPriceNgn !== undefined) return ov.costPriceNgn;
  return typeof p.costPriceNgn === "number" && p.costPriceNgn > 0 ? p.costPriceNgn : null;
}
/** The full sellable catalogue: the data-file products plus any Finds
 *  drafts the admin created from completed sourcing requests (settings).
 *  Drafts start active:false + stock 0, so they stay out of the shop
 *  until the admin publishes them from the Catalog tab. */
export function catalogue(): Product[] {
  const drafts = getFindsDrafts();
  if (!drafts.length) return products;
  const known = new Set(products.map(p => p.slug));
  return [...products, ...drafts.filter(d => d && d.slug && !known.has(d.slug))];
}
